s=rep(s,'''bool VideoSettings::streamConfigured(void)\n{\n    //-- First, check if it's autoconfigured\n''','''bool VideoSettings::streamConfigured(void)\n{\n    if (hikvisionDualEnabled()->rawValue().toBool()) {\n        const bool useMain = hikvisionMainStream()->rawValue().toBool();\n        const QString cam1 = useMain ? hikvisionCam1MainUrl()->rawValue().toString() : hikvisionCam1SubUrl()->rawValue().toString();\n        const QString cam2 = useMain ? hikvisionCam2MainUrl()->rawValue().toString() : hikvisionCam2SubUrl()->rawValue().toString();\n        return !cam1.isEmpty() || !cam2.isEmpty();\n    }\n    //-- First, check if it's autoconfigured\n''','streamConfigured'); write(p,s)

