s=rep(s,'VideoManager *VideoManager::instance()\n{\n    return _videoManagerInstance();\n}\n\nvoid VideoManager::startVideoBackendInit()\n','''VideoManager *VideoManager::instance()\n{\n    return _videoManagerInstance();\n}\n\nbool VideoManager::dualHikvisionEnabled() const\n{\n    return _videoSettings && _videoSettings->hikvisionDualEnabled()->rawValue().toBool();\n}\n\nbool VideoManager::hikvisionMainStream() const\n{\n    return _videoSettings && _videoSettings->hikvisionMainStream()->rawValue().toBool();\n}\n\nvoid VideoManager::toggleHikvisionStream()\n{\n    if (_videoSettings && dualHikvisionEnabled()) {\n        _videoSettings->hikvisionMainStream()->setRawValue(!hikvisionMainStream());\n    }\n}\n\nvoid VideoManager::swapHikvisionCameras()\n{\n    if (!dualHikvisionEnabled()) return;\n    _cameraOrderSwapped = !_cameraOrderSwapped;\n    emit hikvisionCameraOrderChanged();\n    _videoSourceChanged();\n}\n\nQString VideoManager::_hikvisionUriForReceiver(const VideoReceiver *receiver) const\n{\n    if (!receiver || !_videoSettings || !dualHikvisionEnabled()) return QString();\n    int camera = 0;\n    if (receiver->name() == QStringLiteral("videoContent")) camera = primaryHikvisionCamera();\n    else if (receiver->name() == QStringLiteral("camera2Video")) camera = secondaryHikvisionCamera();\n    else return QString();\n    const bool main = hikvisionMainStream();\n    if (camera == 1) return main ? _videoSettings->hikvisionCam1MainUrl()->rawValue().toString() : _videoSettings->hikvisionCam1SubUrl()->rawValue().toString();\n    return main ? _videoSettings->hikvisionCam2MainUrl()->rawValue().toString() : _videoSettings->hikvisionCam2SubUrl()->rawValue().toString();\n}\n\nvoid VideoManager::startVideoBackendInit()\n''','manager helper implementations')
s=rep(s,'    (void) connect(_videoSettings->rtspUrl(), &Fact::rawValueChanged, this, &VideoManager::_videoSourceChanged);\n    (void) connect(_videoSettings->tcpUrl(), &Fact::rawValueChanged, this, &VideoManager::_videoSourceChanged);\n','''    (void) connect(_videoSettings->rtspUrl(), &Fact::rawValueChanged, this, &VideoManager::_videoSourceChanged);\n    (void) connect(_videoSettings->tcpUrl(), &Fact::rawValueChanged, this, &VideoManager::_videoSourceChanged);\n    const auto hikvisionConfigChanged = [this](const QVariant &) { emit hasVideoChanged(); emit isStreamSourceChanged(); _videoSourceChanged(); };\n    (void) connect(_videoSettings->hikvisionCam1MainUrl(), &Fact::rawValueChanged, this, hikvisionConfigChanged);\n    (void) connect(_videoSettings->hikvisionCam1SubUrl(), &Fact::rawValueChanged, this, hikvisionConfigChanged);\n    (void) connect(_videoSettings->hikvisionCam2MainUrl(), &Fact::rawValueChanged, this, hikvisionConfigChanged);\n    (void) connect(_videoSettings->hikvisionCam2SubUrl(), &Fact::rawValueChanged, this, hikvisionConfigChanged);\n    (void) connect(_videoSettings->hikvisionMainStream(), &Fact::rawValueChanged, this, [this](const QVariant &) { emit hikvisionStreamModeChanged(); _videoSourceChanged(); });\n    (void) connect(_videoSettings->hikvisionDualEnabled(), &Fact::rawValueChanged, this, [this](const QVariant &) { _cameraOrderSwapped = false; emit dualHikvisionChanged(); emit hikvisionCameraOrderChanged(); emit hasVideoChanged(); emit isStreamSourceChanged(); _videoSourceChanged(); });\n''','settings connections')
s=rep(s,'    static const QStringList videoStreamList = {\n        "videoContent",\n        "thermalVideo"\n    };\n','''    static const QStringList videoStreamList = {\n        "videoContent",\n        "thermalVideo",\n        "camera2Video"\n    };\n''','receiver list')
