s=rep(s,'bool VideoManager::autoStreamConfigured() const\n{\n    for (VideoReceiver *receiver : _videoReceivers) {\n','''bool VideoManager::autoStreamConfigured() const\n{\n    if (dualHikvisionEnabled()) return false;\n    for (VideoReceiver *receiver : _videoReceivers) {\n''','autoStreamConfigured')
s=rep(s,'bool VideoManager::_updateAutoStream(VideoReceiver *receiver)\n{\n    const QGCVideoStreamInfo *pInfo = receiver->videoStreamInfo();\n','''bool VideoManager::_updateAutoStream(VideoReceiver *receiver)\n{\n    if (dualHikvisionEnabled()) return false;\n    const QGCVideoStreamInfo *pInfo = receiver->videoStreamInfo();\n''','updateAutoStream')
s=rep(s,'    if (receiver->isThermal()) {\n        return settingsChanged;\n    }\n\n    settingsChanged |= _updateUVC(receiver);\n','''    if (receiver->isThermal()) {\n        return settingsChanged;\n    }\n    if (dualHikvisionEnabled()) {\n        if (receiver->name() == QStringLiteral("videoContent") || receiver->name() == QStringLiteral("camera2Video"))\n            settingsChanged |= _updateVideoUri(receiver, _hikvisionUriForReceiver(receiver));\n        return settingsChanged;\n    }\n    if (receiver->name() == QStringLiteral("camera2Video")) {\n        settingsChanged |= _updateVideoUri(receiver, QString());\n        return settingsChanged;\n    }\n\n    settingsChanged |= _updateUVC(receiver);\n''','updateSettings dual branch')
s=rep(s,'    const QString source = _videoSettings->videoSource()->rawValue().toString();\n    const uint32_t timeout = ((source == VideoSettings::videoSourceRTSP) ? _videoSettings->rtspTimeout()->rawValue().toUInt() : 3);\n\n    receiver->start(timeout);\n','''    const QString source = _videoSettings->videoSource()->rawValue().toString();\n    const bool customRtsp = dualHikvisionEnabled() && (receiver->name() == QStringLiteral("videoContent") || receiver->name() == QStringLiteral("camera2Video"));\n    const uint32_t timeout = ((customRtsp || source == VideoSettings::videoSourceRTSP) ? _videoSettings->rtspTimeout()->rawValue().toUInt() : 3);\n\n    receiver->start(timeout);\n''','startReceiver timeout')
s=rep(s,'        if (!receiver->isThermal()) {\n            _streaming = active;\n            emit streamingChanged();\n        }\n','''        if (receiver->name() == QStringLiteral("videoContent")) {\n            _streaming = active;\n            emit streamingChanged();\n        }\n''','streaming callback')
s=rep(s,'        if (!receiver->isThermal()) {\n            _decoding = active;\n            emit decodingChanged();\n        }\n','''        if (receiver->name() == QStringLiteral("videoContent")) {\n            _decoding = active;\n            emit decodingChanged();\n        } else if (receiver->name() == QStringLiteral("camera2Video")) {\n            _secondaryDecoding = active;\n            emit secondaryDecodingChanged();\n        }\n''','decoding callback')
s=rep(s,'        if (!receiver->isThermal()) {\n            _recording = active;\n            if (!active) {\n                _subtitleWriter->stopCapturingTelemetry();\n            }\n            emit recordingChanged(_recording);\n        }\n','''        if (receiver->name() == QStringLiteral("videoContent")) {\n            _recording = active;\n            if (!active) _subtitleWriter->stopCapturingTelemetry();\n            emit recordingChanged(_recording);\n        }\n''','recording callback')
s=rep(s,'        if (!receiver->isThermal()) {\n            _subtitleWriter->startCapturingTelemetry(filename, videoSize());\n        }\n','''        if (receiver->name() == QStringLiteral("videoContent")) {\n            _subtitleWriter->startCapturingTelemetry(filename, videoSize());\n        }\n''','recordingStarted callback')
s=rep(s,'        if (!receiver->isThermal()) {\n            _videoSize = size;\n            emit videoSizeChanged();\n            emit aspectRatioChanged();\n        }\n','''        if (receiver->name() == QStringLiteral("videoContent")) {\n            _videoSize = size;\n            emit videoSizeChanged();\n            emit aspectRatioChanged();\n        }\n''','videoSize callback'); write(p,s)

