write('src/FlyView/HikvisionSecondVideo.qml', '''import QtQuick\nimport QtMultimedia\n\nimport QGroundControl\nimport QGroundControl.Controls\n\nItem {\n    id: root\n    clip: true\n    Rectangle { anchors.fill: parent; color: "black" }\n    Image { anchors.fill: parent; source: "/res/NoVideoBackground.jpg"; fillMode: Image.PreserveAspectCrop; visible: !QGroundControl.videoManager.secondaryDecoding }\n    VideoOutput {\n        objectName: "camera2Video"\n        anchors.fill: parent\n        visible: QGroundControl.videoManager.secondaryDecoding\n        fillMode: QGroundControl.settingsManager.videoSettings.videoFit.rawValue === 2 ? VideoOutput.PreserveAspectCrop : VideoOutput.PreserveAspectFit\n    }\n    Rectangle {\n        anchors.left: parent.left; anchors.top: parent.top; anchors.margins: ScreenTools.defaultFontPixelHeight * 0.35\n        width: cameraLabel.implicitWidth + ScreenTools.defaultFontPixelWidth * 2; height: cameraLabel.implicitHeight + ScreenTools.defaultFontPixelHeight * 0.5\n        radius: ScreenTools.defaultFontPixelWidth * 0.5; color: Qt.rgba(0,0,0,0.70)\n        QGCLabel { id: cameraLabel; anchors.centerIn: parent; color: "white"; font.bold: true; text: qsTr("CAM %1").arg(QGroundControl.videoManager.secondaryHikvisionCamera) }\n    }\n    Rectangle {\n        anchors.right: parent.right; anchors.top: parent.top; anchors.margins: ScreenTools.defaultFontPixelHeight * 0.35\n        width: streamLabel.implicitWidth + ScreenTools.defaultFontPixelWidth * 2; height: streamLabel.implicitHeight + ScreenTools.defaultFontPixelHeight * 0.5\n        radius: ScreenTools.defaultFontPixelWidth * 0.5; color: Qt.rgba(0,0,0,0.70)\n        QGCLabel { id: streamLabel; anchors.centerIn: parent; color: "white"; font.bold: true; text: QGroundControl.videoManager.hikvisionMainStream ? qsTr("MAIN") : qsTr("SUB") }\n    }\n    MouseArea { anchors.fill: parent; cursorShape: Qt.PointingHandCursor; onClicked: QGroundControl.videoManager.swapHikvisionCameras() }\n}\n''')

