# Preserve previous RTSP stability patch
p='src/VideoManager/VideoReceiver/GStreamer/GstSourceFactory.cc'; s=read(p)
if 'configureRtpDepayLossRecovery' not in s:
    s=rep(s,'void configureAutopluggedParser([[maybe_unused]] GstBin* bin, [[maybe_unused]] GstBin* subBin, GstElement* element,\n                                [[maybe_unused]] gpointer data)\n{\n    configureH26xParser(element);\n}\n','''void configureRtpDepayLossRecovery(GstElement* element)\n{\n    GstElementFactory* factory = gst_element_get_factory(element);\n    if (!factory) return;\n    const char* factoryName = gst_plugin_feature_get_name(GST_PLUGIN_FEATURE(factory));\n    const bool h264 = g_strcmp0(factoryName, "rtph264depay") == 0;\n    const bool h265 = g_strcmp0(factoryName, "rtph265depay") == 0;\n    if (!h264 && !h265) return;\n    GObjectClass* c = G_OBJECT_GET_CLASS(element);\n    if (g_object_class_find_property(c, "wait-for-keyframe")) g_object_set(element, "wait-for-keyframe", TRUE, nullptr);\n    if (g_object_class_find_property(c, "request-keyframe")) g_object_set(element, "request-keyframe", TRUE, nullptr);\n}\n\nvoid configureAutopluggedParser([[maybe_unused]] GstBin* bin, [[maybe_unused]] GstBin* subBin, GstElement* element,\n                                [[maybe_unused]] gpointer data)\n{\n    configureH26xParser(element);\n    configureRtpDepayLossRecovery(element);\n}\n''','keyframe recovery')
if 'kRtspMinLatencyMs' not in s:
    s=rep(s,'    // protocols mask enables TCP-interleaved fallback when UDP is blocked; without it\n    // firewalled networks hang until tcp-timeout instead of negotiating TCP.\n    constexpr GstRTSPLowerTrans kRtspProtocols =\n        static_cast<GstRTSPLowerTrans>(GST_RTSP_LOWER_TRANS_UDP | GST_RTSP_LOWER_TRANS_TCP);\n\n    // rtspsrc always owns an internal jitterbuffer, so None maps to zero playout latency and no retransmission.\n    const guint rtspLatencyMs = (config.jitterBuffer == JitterBuffer::None) ? 0u : latencyMs;\n    const gboolean doRetransmission =\n        ((config.jitterBuffer != JitterBuffer::None) && config.doRetransmission) ? TRUE : FALSE;\n    const gboolean dropOnLatency = (config.jitterBuffer == JitterBuffer::Buffered) ? FALSE : TRUE;\n','''    constexpr GstRTSPLowerTrans kRtspProtocols = static_cast<GstRTSPLowerTrans>(GST_RTSP_LOWER_TRANS_TCP);\n    constexpr guint kRtspMinLatencyMs = 120u;\n    constexpr guint kRtspMaxLatencyMs = 250u;\n    guint rtspLatencyMs = latencyMs;\n    if (rtspLatencyMs < kRtspMinLatencyMs) rtspLatencyMs = kRtspMinLatencyMs;\n    else if (rtspLatencyMs > kRtspMaxLatencyMs) rtspLatencyMs = kRtspMaxLatencyMs;\n    const gboolean doRetransmission = FALSE;\n    const gboolean dropOnLatency = TRUE;\n''','tcp bounded latency')
write(p,s)
print('Dual Hikvision patch applied successfully')
